#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    char *endptr;
    long val = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }
    int shift = (int)val;
    shift %= 26;
    if (shift < 0) shift += 26;
    const char *text = argv[2];
    for (size_t i = 0; text[i] != '\0'; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (char)('A' + (c - 'A' + shift) % 26);
        } else if (c >= 'a' && c <= 'z') {
            c = (char)('a' + (c - 'a' + shift) % 26);
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
